    await userEvent.type(maxAttemptsInput, '10');

    const submitButton = screen.getByText('Create Campaign');
    fireEvent.click(submitButton);

    await waitFor(() => {
      expect(screen.getByText('Max attempts must be between 1 and 5')).toBeInTheDocument();
